const {readFileSync}=require('node:fs');
const {test}=require('node:test');
const assert=require('node:assert/strict');
const vm=require('node:vm');
const script=readFileSync('dashboard/app.js','utf8');
const logic=script.split('let state=initialState()')[0];
const api=vm.runInNewContext(logic+';({catalog,filterCatalog,emptyFilters,normalizeFilters,parseProfileText,safeHttpURL,skillGaps,normalizeSearch,initialState,normalizeState,reconcileModelSelection,modelProbePassed,esc})',{URL,Date});
const search=(query='',filters={})=>api.filterCatalog(api.catalog,query,{...api.emptyFilters(),...filters});

test('sumber bawaan mencakup Google tanpa mengaktifkan ulang sumber yang sengaja dimatikan',()=>{assert.equal(api.normalizeState({}).settings.sources.join(','),'freehire,arbeitnow,arbeitnow-uk,kalibrr,jobstreet,glints,google,google-careers');assert.equal(api.normalizeState({settings:{sources:[]}}).settings.sources.length,0);assert.equal(api.normalizeState({settings:{sources:['freehire']}}).settings.sources.join(','),'freehire');assert.equal(api.normalizeState({settings:{sources:['freehire','arbeitnow','arbeitnow-uk','kalibrr','jobstreet','glints']}}).settings.sources.at(-1),'google-careers');assert.equal(api.normalizeState({searchVersion:1,settings:{sources:['freehire','arbeitnow','arbeitnow-uk','kalibrr','jobstreet','glints']}}).settings.sources.includes('google'),false);assert.throws(()=>api.normalizeState({settings:{sources:['unknown']}}),/Sumber/);});
test('pengaturan board membatasi jumlah dan status aktif harus boolean',()=>{assert.throws(()=>api.normalizeState({settings:{boards:Array.from({length:7},(_,i)=>({type:'lever',slug:'board'+i}))}}),/Sumber/);assert.throws(()=>api.normalizeState({settings:{boards:[{type:'lever',slug:'valid',enabled:'false'}]}}),/Sumber/);});
