test('daftar awal mencakup status belum pasti, menyaring ditutup dan menyediakan arsip',()=>{assert.ok(search().some(j=>j.status==='unknown'));assert.ok(search().every(j=>['open','unknown'].includes(j.status)));assert.ok(search('',{status:'all'}).some(j=>j.status==='closed'));assert.ok(search('',{status:'expired'}).every(j=>j.status==='expired'));});
test('filter aktif menyertakan unknown dan migrasi sekali saja mempertahankan pilihan berikutnya',()=>{
 assert.equal(api.emptyFilters().status,'active');assert.equal(api.normalizeFilters().status,'active');assert.equal(api.normalizeFilters({status:'active'}).status,'active');assert.equal(api.normalizeState({filters:{status:'open'}}).filters.status,'active');assert.equal(api.normalizeState({searchVersion:1,filters:{status:'open'}}).filters.status,'open');assert.equal(api.normalizeFilters({status:'invalid'}).status,'active');
 for(const status of ['all','open','unknown','closed','expired'])assert.equal(api.normalizeFilters({status}).status,status);
});
test('status efektif menyaring tenggat lewat tanpa membuka status unknown atau closed',()=>{
 const now=Date.parse('2026-10-25T10:00:00Z');class FixedDate extends Date{constructor(...args){super(...(args.length?args:[now]));}static now(){return now;}}
 const filtersApi=vm.runInNewContext(logic+';({filterCatalog,emptyFilters})',{URL,Date:FixedDate}),base={...api.catalog[0],mock:false,checkedAt:'2026-10-24T10:00:00Z'},rows=[{...base,id:1,status:'open',deadline:'2026-10-26T10:00:00Z'},{...base,id:2,status:'open',deadline:'2026-10-24T10:00:00Z'},{...base,id:3,status:'unknown',deadline:'2026-10-26T10:00:00Z'},{...base,id:4,status:'closed',deadline:'2026-10-26T10:00:00Z'},{...base,id:5,status:'open',deadline:'invalid'},{...base,id:6,status:'expired',deadline:'2026-10-26T10:00:00Z'}];
 for(const [status,expected] of [['open',[1,5]],['all',[1,2,3,4,5,6]],['unknown',[3]],['closed',[4]],['expired',[2,6]]])assert.deepEqual(Array.from(filtersApi.filterCatalog(rows,'',{...filtersApi.emptyFilters(),status}),job=>job.id),expected,status);
 assert.equal(rows[1].status,'open');assert.equal(rows[1].checkedAt,base.checkedAt);
});
test('filter tenggat tanggal saja berlaku hingga akhir hari UTC',()=>{
 let now=Date.parse('2026-10-25T23:59:59.999Z');class FixedDate extends Date{constructor(...args){super(...(args.length?args:[now]));}static now(){return now;}}
 const filtersApi=vm.runInNewContext(logic+';({filterCatalog,emptyFilters})',{URL,Date:FixedDate}),row={...api.catalog[0],mock:false,status:'open',deadline:'2026-10-25'},filters={...filtersApi.emptyFilters(),status:'open'};
 assert.equal(filtersApi.filterCatalog([row],'',filters).length,1);now=Date.parse('2026-10-26T00:00:00Z');assert.equal(filtersApi.filterCatalog([row],'',filters).length,0);
});
