function taskHarness(searchJobs=[],verificationEvidence=null,visibleInputs={},responses={}){
 const requests=[],dialogs=[],downloads=[],handlers={};
 const context=vm.createContext({URL,Date,Intl,AbortController,setTimeout,clearTimeout,
  FormData:class {constructor(form){this.values=Object.entries(form.values||{});}get(key){return this.values.find(([name])=>name===key)?.[1]??null;}[Symbol.iterator](){return this.values[Symbol.iterator]();}},
  document:{getElementById:id=>Object.hasOwn(visibleInputs,id)?{value:visibleInputs[id]}:null,addEventListener:(name,handler)=>{handlers[name]=handler;}},
  recordDialog:(...args)=>dialogs.push(args),recordDownload:(...args)=>downloads.push(args),
  fetch:async(path,options)=>{const payload=JSON.parse(options.body);requests.push({path,payload});if(Object.hasOwn(responses,path))return {ok:responses[path].http_ok!==false,status:responses[path].status||200,json:async()=>responses[path].body};return {ok:true,json:async()=>path==='/api/verify'?{ok:true,evidence:verificationEvidence}:path==='/api/search'?{ok:true,jobs:searchJobs,sources:[],searched_at:'2026-10-24T12:00:00Z'}:({ok:true,tool_calling:true,json_output:true,output:payload.task==='document'?{title:'Draf uji',content:'Konten fixture untuk pengujian pengiriman konteks.',review_notes:[],profile_complete:false}:{reply:'Balasan fixture.'}})};}
 });
 const eventSource=script.slice(script.indexOf("document.addEventListener('click'"),script.indexOf("document.addEventListener('keydown'"));
 const methods=vm.runInContext(viewSource+';runTask=async(title,operation)=>operation();navigate=()=>{};closeDialog=()=>{};render=()=>{};toast=()=>{};showDialog=(...args)=>recordDialog(...args);downloadFile=(...args)=>recordDownload(...args);'+eventSource+';({actions,callApi:api,setPage:value=>{page=value},createDocument,performSearch,searchInternships,recheckSource,sourcePage,allJobs,aiTask,interviewProfile,questionsForJob,generateLearning,setState:value=>{state=normalizeState(value)},setModels:value=>{models=value},getState:()=>state})',context);
 return {requests,dialogs,downloads,handlers,...methods};
}

