function preparationHarness(responder){
 const requests=[],dialogs=[],downloads=[],nodes={'practice-answer':{isConnected:true,focus(){}},'practice-feedback':{isConnected:true,innerHTML:'',textContent:''},button:{isConnected:true,disabled:false}};
 const context=vm.createContext({URL,Date,Intl,Blob,AbortController,setTimeout,clearTimeout,document:{getElementById:id=>nodes[id]||null,querySelector:selector=>selector==='#practice-form button'?nodes.button:null},fetch:async(path,options)=>{const payload=JSON.parse(options.body);requests.push({path,payload,options});if(path==='/api/documents/pdf')return responder?responder(path,payload):{ok:true,headers:{get:()=> 'application/pdf'},blob:async()=>new Blob(['%PDF-1.7\nfixture'],{type:'application/pdf'})};const output=responder?await responder(path,payload):payload.task==='interview'?{summary:'Latihan',questions:Array.from({length:12},(_,i)=>({question:'Pertanyaan '+(i+1),focus:'Fokus <aman>',suggested_structure:'Situasi, tindakan, hasil.'})),feedback:'Petunjuk latihan',profile_complete:false}:feedbackFixture;return {ok:true,json:async()=>({ok:true,tool_calling:true,json_output:true,output})};},recordDialog:(...args)=>dialogs.push(args),recordDownload:(...args)=>downloads.push(args)});
 const methods=vm.runInContext(viewSource+';runTask=async(title,operation)=>{try{await operation();}catch{}};render=()=>{};toast=()=>{};showError=()=>{};logActivity=()=>{};showDialog=(...args)=>recordDialog(...args);downloadFile=(...args)=>recordDownload(...args);({showPractice,practiceFeedback,learningFeedback,saveResponseDraft,interviewResponseKey,feedbackContent,downloadPDF,setIndex:value=>{practiceIndex=value},setState:value=>{state=normalizeState(value)},setModels:value=>{models=value},getState:()=>state})',context);
 const fixture=editableFixture();fixture.model='router/test';methods.setState(fixture);methods.setModels([{id:'router/test'}]);return {...methods,requests,dialogs,downloads,nodes};
}
