function persistenceHarness(conflict=false){
 const requests=[],statuses=[],errors=[],downloads=[];let sequence=0;
 const context=vm.createContext({URL,Date,Intl,Blob,AbortController,setTimeout:()=>0,clearTimeout:()=>{},revisionSeed:'a'.repeat(64),recordStatus:text=>statuses.push(text),recordError:text=>errors.push(text),recordDownload:(...args)=>downloads.push(args),fetch:async(path,options)=>{requests.push({path,options,payload:JSON.parse(options.body)});if(conflict===true||(conflict==='delete'&&options.method==='DELETE'))return {ok:false,status:409,json:async()=>({ok:false,error:'Data berubah di tab lain. Muat ulang dashboard.'})};const revision=(++sequence===1?'b':'c').repeat(64);return {ok:true,json:async()=>({ok:true,revision,state:{profile:{fullName:'Hasil pemulihan'},cv:null,cvHistory:[],confirmed:false}})};}});
 const methods=vm.runInContext(viewSource+';booted=true;sessionToken="fixture-token";if(typeof stateRevision!=="undefined")stateRevision=revisionSeed;setSaveStatus=text=>recordStatus(text);showError=text=>recordError(text);render=()=>{};closeDialog=()=>{};toast=()=>{};downloadFile=(...args)=>recordDownload(...args);({actions,persist,flushState,downloadPDF,deleteCV,getState:()=>state,transition:()=>criticalTransition,setState:value=>{state=normalizeState(value)},setRestore:value=>{pendingRestore=value},revision:()=>typeof stateRevision==="undefined"?"missing":stateRevision,sequences:()=>({saveSequence,savedSequence})})',context);
 return {...methods,requests,statuses,errors,downloads};
}
