function portalJob(id,provider='glints'){return {...verificationJob(),id,providerId:provider,sourceType:'portal',sourceName:provider==='glints'?'Glints':'Jobstreet',title:'Operations Intern '+id};}
function integrationProvider(id='glints',updates={}){return {id,name:id==='glints'?'Glints':'Jobstreet',mode:id==='glints'?'public_page':'local_browser',browser_open:false,session_saved:false,login_status:'not_checked',access_status:'not_checked',message:'Belum diperiksa.',checked_at:null,last_sync_at:null,result_count:null,last_query:'',...updates};}
function portalSyncResult(jobs=[],provider='glints'){return {ok:true,provider:integrationProvider(provider,{access_status:'ok',result_count:jobs.length,last_sync_at:'2026-10-25T05:00:00Z'}),jobs,sources:[{id:provider,name:provider==='glints'?'Glints':'Jobstreet',status:'ok',count:jobs.length}],searched_at:'2026-10-25T05:00:00Z'};}
function integrationHarness({response,query,conflict=false,providers:initialProviders,now}={}){
 const requests=[],errors=[],dialogs=[],handlers={},inputs=query===undefined?{}:{'integration-query':{value:query}},providers=initialProviders?[...initialProviders]:[integrationProvider(),integrationProvider('jobstreet')];
 const ClockDate=now===undefined?Date:class extends Date{constructor(...args){super(...(args.length?args:[now]));}static now(){return now;}};
 const context=vm.createContext({URL,Date:ClockDate,Intl,AbortController,setTimeout:()=>0,clearTimeout:()=>{},document:{getElementById:id=>inputs[id]||null,addEventListener:(name,handler)=>{handlers[name]=handler;}},recordError:text=>errors.push(text),recordDialog:(...args)=>dialogs.push(args),fetch:async(path,options={})=>{
  const payload=options.body===undefined?undefined:JSON.parse(options.body);requests.push({path,options,payload});
  if(path==='/api/state')return {ok:!conflict,status:conflict?409:200,json:async()=>conflict?{ok:false,error:'Data berubah di tab lain.'}:{ok:true,revision:'b'.repeat(64)}};
  if(path==='/api/integrations')return {ok:true,json:async()=>({ok:true,providers})};
  const id=path.split('/')[3],body=typeof response==='function'?await response(path,payload):response||{ok:true,provider:integrationProvider(id,{browser_open:true,session_saved:true})};
  if(body.provider){const index=providers.findIndex(provider=>provider.id===body.provider.id);if(index>=0)providers[index]=body.provider;}
  return {ok:true,status:200,json:async()=>body};
 }});
 const eventSource=script.slice(script.indexOf("document.addEventListener('click'"),script.indexOf("document.addEventListener('keydown'"));
 const methods=vm.runInContext(viewSource+';booted=true;sessionToken="integration-token";stateRevision="a".repeat(64);page="integrasi";render=()=>{};setSaveStatus=()=>{};toast=()=>{};closeDialog=()=>{};showError=text=>recordError(text);showDialog=(...args)=>recordDialog(...args);'+eventSource+';({actions,mergePortalSync:typeof mergePortalSync==="function"?mergePortalSync:null,refreshIntegrations:typeof refreshIntegrations==="function"?refreshIntegrations:null,integrationsView:typeof integrationsView==="function"?integrationsView:null,runIntegrationAction:typeof runIntegrationAction==="function"?runIntegrationAction:null,getState:()=>state,setState:value=>{state=normalizeState(value)},getProviders:()=>typeof integrationProviders==="undefined"?[]:integrationProviders})',context);
 return {...methods,requests,errors,dialogs,handlers,inputs};
}
test('refresh integrasi memeriksa ulang sesi tersimpan dengan waktu login kosong rusak atau kedaluwarsa',async()=>{
 const now=Date.parse('2026-10-25T10:00:00Z'),fresh=new Date(now).toISOString();
 for(const checked of [null,'invalid','2026-10-25T09:29:59Z']){
  const providers=[integrationProvider('glints',{session_saved:true,login_checked_at:checked,last_query:'administrasi'}),integrationProvider('jobstreet',{session_saved:true,login_checked_at:checked})],h=integrationHarness({now,providers,response:path=>({ok:true,provider:integrationProvider(path.split('/')[3],{session_saved:true,login_status:'signed_in',login_checked_at:fresh})})});h.setState({query:checked===null?'':'keuangan'});await h.refreshIntegrations();
  assert.equal(h.requests[0].path,'/api/integrations');const checks=h.requests.filter(request=>request.options.method==='POST');assert.deepEqual(checks.map(request=>request.path),['/api/integrations/glints/check','/api/integrations/jobstreet/check']);assert.deepEqual(checks.map(request=>request.payload.query),['administrasi',checked===null?'magang':'keuangan']);assert.ok(checks.every(request=>request.options.headers['X-SuperWork-Token']==='integration-token'));assert.ok(h.getProviders().every(provider=>provider.login_status==='signed_in'));
 }
});
