 const now=Date.parse('2026-10-25T10:00:00Z'),fresh='2026-10-25T09:55:00Z',provider=id=>integrationProvider(id,{session_saved:true,login_checked_at:fresh}),h=integrationHarness({now,providers:[provider('glints'),provider('jobstreet'),integrationProvider('../unknown',{session_saved:true,login_checked_at:null})],response:path=>({ok:true,provider:provider(path.split('/')[3])})});
