test('profil browser tersimpan tidak mengaku login dan pesan provider tetap berupa teks',async()=>{
 const h=integrationHarness({response:{ok:true,provider:integrationProvider('glints',{session_saved:true,access_status:'blocked',message:'<img src=x onerror=alert(1)>'})}});await h.runIntegrationAction('glints','open');const html=h.integrationsView();assert.match(html,/Profil browser tersimpan/);assert.match(html,/Login belum diperiksa/);assert.ok(!html.includes('Akun terdeteksi masuk'));assert.ok(html.includes('&lt;img'));assert.ok(!html.includes('<img'));assert.match(html,/Perlu tindakan Anda/);
});
test('tombol portal memakai input terlihat, token mutasi dan body kontrak',async()=>{
 const h=integrationHarness({query:'akuntansi',response:(path)=>path.endsWith('/sync')?portalSyncResult([portalJob(9500)]):{ok:true,provider:integrationProvider('glints',{access_status:'ok'})}});h.setState({query:'operations',filters:{employment:'Magang'}});await h.runIntegrationAction('glints','open');await h.runIntegrationAction('glints','check');await h.runIntegrationAction('glints','sync');
 const requests=h.requests.filter(item=>item.path.startsWith('/api/integrations/'));assert.equal(JSON.stringify(requests[0].payload),'{}');assert.equal(JSON.stringify(requests[1].payload),'{"query":"akuntansi"}');assert.equal(requests[2].payload.query,'akuntansi');assert.equal(requests[2].payload.filters.employment,'Magang');assert.ok(requests.every(request=>request.options.headers['X-SuperWork-Token']==='integration-token'));assert.ok(h.requests.some(request=>request.path==='/api/state'&&request.options.headers['If-Match']==='"'+'a'.repeat(64)+'"'));assert.equal(h.getState().liveJobs[0].id,9500);assert.equal(h.getState().query,'akuntansi');
});
test('kata kunci kosong memakai magang dan input tidak valid tidak memanggil endpoint',async()=>{
 const h=integrationHarness({query:''});h.setState({query:'operations'});await h.runIntegrationAction('glints','check');assert.equal(h.requests.find(item=>item.path.endsWith('/check')).payload.query,'magang');
 h.inputs['integration-query'].value='x'.repeat(201);const count=h.requests.length;await assert.rejects(h.runIntegrationAction('glints','sync'),/200/);await assert.rejects(h.runIntegrationAction('../other','open'));await assert.rejects(h.runIntegrationAction('glints','other'));assert.equal(h.requests.length,count);
});
test('nonaktif sumber tidak logout dan sinkron sumber nonaktif ditolak',async()=>{
 const h=integrationHarness();h.setState(editableFixture());const profile=JSON.stringify(h.getState().profile),documents=JSON.stringify(h.getState().documents);h.handlers.change({target:{id:'',dataset:{jobSource:'glints'},checked:false}});assert.ok(!h.getState().settings.sources.includes('glints'));assert.equal(h.requests.length,0);await h.runIntegrationAction('glints','sync');assert.equal(h.requests.length,0);assert.equal(JSON.stringify(h.getState().profile),profile);assert.equal(JSON.stringify(h.getState().documents),documents);
});
test('hapus sesi perlu konfirmasi dan mempertahankan lowongan serta data pribadi',async()=>{
 const h=integrationHarness(),fixture={...editableFixture(),liveJobs:[portalJob(9500)],saved:[101,9500]};h.setState(fixture);const before=JSON.stringify(h.getState());await h.actions['integration-disconnect']({dataset:{id:'glints'}});assert.equal(h.requests.length,0);assert.match(h.dialogs.at(-1)[1],/tidak menghapus/i);await h.actions['integration-disconnect-confirm']({dataset:{id:'glints'}});const request=h.requests.find(item=>item.path.endsWith('/disconnect'));assert.equal(JSON.stringify(request.payload),'{"confirm":true}');assert.equal(h.getState().documents.length,fixture.documents.length);assert.equal(h.getState().liveJobs[0].id,9500);assert.equal(h.getState().profile.fullName,fixture.profile.fullName);assert.equal(JSON.parse(before).saved.length,h.getState().saved.length);
});
test('kegagalan sync memperbarui status faktual tanpa menghapus hasil lama',async()=>{
 const h=integrationHarness({query:'magang',response:{ok:false,error:'Portal meminta tindakan pengguna.',provider:integrationProvider('glints',{access_status:'action_required',message:'Selesaikan pemeriksaan di browser.'})}});h.setState({liveJobs:[portalJob(9500)],lastSearchJobIds:[9500]});await h.runIntegrationAction('glints','sync');assert.equal(h.getState().liveJobs[0].id,9500);assert.deepEqual(Array.from(h.getState().lastSearchJobIds),[9500]);assert.ok(h.requests.some(item=>item.path==='/api/integrations'));assert.equal(h.getProviders()[0].access_status,'action_required');assert.ok(h.errors.some(error=>error.includes('Portal meminta')));
});
test('konflik CAS menghentikan operasi portal sebelum membuka browser',async()=>{
 const h=integrationHarness({conflict:true});await h.runIntegrationAction('jobstreet','open');assert.equal(h.requests.filter(item=>item.path.startsWith('/api/integrations/')).length,0);assert.ok(h.errors.some(error=>error.includes('Data berubah')));
});
test('sinkron mengenali marker portal lama, memperbarui posisi yang sama dan menolak tabrakan manual',()=>{
 const h=integrationHarness(),legacy={...portalJob(9500),providerId:undefined},other={...portalJob(9600,'jobstreet'),providerId:undefined},before=api.normalizeState({liveJobs:[legacy,other],lastSearchJobIds:[9500,9600]});const updated={...portalJob(9500),title:'Posisi yang telah diperbarui'},next=h.mergePortalSync(before,'glints',portalSyncResult([updated]));assert.equal(next.liveJobs.find(job=>job.id===9500).title,updated.title);assert.equal(next.liveJobs.filter(job=>job.id===9500).length,1);assert.equal(next.liveJobs.find(job=>job.id===9600).sourceName,'Jobstreet');assert.deepEqual(Array.from(next.lastSearchJobIds),[9600,9500]);
 const manual=api.normalizeState({manualJobs:[portalJob(9500)]});assert.throws(()=>h.mergePortalSync(manual,'glints',portalSyncResult([updated])),/Sumber hasil/);
});
test('periksa akses yang diblokir ditampilkan faktual dan tombol dibuka kembali setelah selesai',async()=>{
 const h=integrationHarness({response:{ok:true,provider:integrationProvider('jobstreet',{browser_open:true,session_saved:true,login_status:'signed_out',access_status:'blocked',message:'Selesaikan pemeriksaan di browser resmi.'})}});await h.runIntegrationAction('jobstreet','check');const html=h.integrationsView();assert.match(html,/Belum masuk akun/);assert.match(html,/Perlu tindakan Anda/);assert.match(html,/Selesaikan pemeriksaan di browser resmi/);assert.equal(h.errors.length,0);assert.match(html,/data-action="integration-check"[^>]*data-id="jobstreet"[^>]*>/);assert.ok(!/data-action="integration-check"[^>]*disabled/.test(html));
});
test('proses portal yang berjalan tidak dikirim dua kali dan kontrol menampilkan sibuk',async()=>{
 let complete;const h=integrationHarness({response:()=>new Promise(resolve=>{complete=resolve;})}),first=h.runIntegrationAction('glints','check');for(let i=0;i<20&&!complete;i++)await Promise.resolve();assert.equal(typeof complete,'function');const busy=h.integrationsView();assert.match(busy,/data-action="integration-check"[^>]*disabled/);await h.runIntegrationAction('glints','sync');assert.equal(h.requests.filter(item=>item.path.startsWith('/api/integrations/')).length,1);complete({ok:true,provider:integrationProvider('glints',{access_status:'ok'})});await first;assert.ok(!/data-action="integration-check"[^>]*disabled/.test(h.integrationsView()));assert.equal(h.errors.length,0);
});
